from pipeline.i18n_extensions import merge_into as _merge_extension_i18n

_merge_extension_i18n(TRANSLATIONS)

_LANGUAGE_SYSTEM_RULES: dict[str, str] = {
    "en": (
        "LANGUAGE: Respond to the user entirely in English. "
        "Do not switch languages unless the user explicitly requests another language "
        "(e.g. 'in Chinese', '用中文')."
    ),
    "zh_tw": (
        "LANGUAGE: Respond to the user entirely in Traditional Chinese (繁體中文). "
        "This is the app language setting — keep using 繁體中文 even when the user writes "
        "in English (e.g. 'tell me a story', 'summarize'). "
        "Only switch if they explicitly request another language "
        "(e.g. 'in English', 'reply in English', '用英文')."
    ),
    "zh_cn": (
        "LANGUAGE: Respond to the user entirely in Simplified Chinese (简体中文). "
        "This is the app language setting — keep using 简体中文 even when the user writes "
        "in English (e.g. 'tell me a story', 'summarize'). "
        "Only switch if they explicitly request another language "
        "(e.g. 'in English', 'reply in English', '用英文')."
    ),
    "es": (
        "LANGUAGE: Respond to the user entirely in Spanish (Español). "
        "This is the app language setting — keep using Spanish even when the user writes "
        "in English (e.g. 'tell me a story', 'summarize'). "
        "Only switch if they explicitly request another language "
        "(e.g. 'in English', 'reply in English', 'en inglés')."
    ),
    "de": (
        "LANGUAGE: Respond to the user entirely in German (Deutsch). "
        "This is the app language setting — keep using German even when the user writes "
        "in English (e.g. 'tell me a story', 'summarize'). "
        "Only switch if they explicitly request another language "
        "(e.g. 'in English', 'reply in English', 'auf Englisch')."
    ),
}


def normalize_locale(raw: str | None) -> str:
    if not raw:
        return DEFAULT_LOCALE
    key = str(raw).strip().lower().replace(" ", "_")
    return _LOCALE_ALIASES.get(key, DEFAULT_LOCALE)


def get_locale(settings: dict | None = None) -> str:
    if settings is None:
        try:
            from services.session import state

            settings = state.current_settings or {}
        except Exception:
            settings = {}
    return normalize_locale(settings.get("language"))


def is_cjk_locale(locale: str | None = None) -> bool:
    loc = normalize_locale(locale) if locale else get_locale()
    return loc in ("zh_tw", "zh_cn")


_S2T_CONVERTER = None


def to_traditional(text: str) -> str:
    """Convert Simplified Chinese text to Traditional (OpenCC s2t).

    Whisper/SenseVoice both emit Simplified script for "zh" regardless of UI
    locale, so callers targeting zh_tw route dictation output through this.
    """
    if not text:
        return text
    global _S2T_CONVERTER
    if _S2T_CONVERTER is None:
        from opencc import OpenCC

        _S2T_CONVERTER = OpenCC("s2t")
    return _S2T_CONVERTER.convert(text)


def maybe_traditional(text: str) -> str:
    """Traditional Chinese by default (matches the SOTA reference app) — gated by
    the "traditional_chinese" setting, which covers Chinese output from any speech
    engine (SenseVoice live dictation, Whisper file transcription). OpenCC s2t passes
    non-Chinese text through unchanged, so this is safe to call regardless of the
    detected language."""
    if not text:
        return text
    try:
        from services.session import state

        want = bool((state.current_settings or {}).get("traditional_chinese", True))
    except Exception:
        want = True
    if not want:
        return text
    return to_traditional(text)


def panel_heading_class() -> str:
    if is_cjk_locale():
        return "text-xs font-bold tracking-wide leading-snug"
    return "text-[11px] font-bold tracking-widest leading-none"


def section_label_class(*extra: str) -> str:
    base = "text-xs font-bold tracking-wide" if is_cjk_locale() else "text-[10px] font-bold tracking-widest"
    return f"{base} {' '.join(extra)}".strip()


def progress_stage_label_class(muted: str) -> str:
    if is_cjk_locale():
        return f"text-[11px] tracking-wide font-bold {muted}"
    return f"text-[8px] uppercase tracking-[0.2em] font-bold {muted}"


def topbar_tagline_class(muted: str) -> str:
    if is_cjk_locale():
        return f"text-[11px] tracking-wide leading-snug {muted}"
    return f"text-[10px] tracking-wider {muted}"


def upload_retention_select_options() -> dict[int, str]:
    return {
        0: t("settings.upload_retention_never"),
        1: t("settings.upload_retention_1"),
        3: t("settings.upload_retention_3"),
        7: t("settings.upload_retention_7"),
        14: t("settings.upload_retention_14"),
        30: t("settings.upload_retention_30"),
    }


def t(key: str, *, locale: str | None = None, **kwargs) -> str:
    loc = normalize_locale(locale) if locale else get_locale()
    table = TRANSLATIONS.get(loc) or TRANSLATIONS[DEFAULT_LOCALE]
    text = table.get(key) or TRANSLATIONS[DEFAULT_LOCALE].get(key) or key
    if kwargs:
        try:
            return text.format(**kwargs)
        except (KeyError, ValueError):
            return text
    return text


