def language_system_rule(locale: str | None = None) -> str:
    loc = normalize_locale(locale) if locale else get_locale()
    return _LANGUAGE_SYSTEM_RULES.get(loc, _LANGUAGE_SYSTEM_RULES[DEFAULT_LOCALE])


def infer_language_from_query(user_input: str) -> str | None:
    """Detect requested response language from the user message (overrides UI locale)."""
    text = (user_input or "").strip()
    lower = text.lower()
    if not text:
        return None
    # Target-language requests first (incl. translate-to-X), before CJK fallback —
    # otherwise 「翻譯成英語」 would force Chinese because the query contains Han chars.
    if any(
        phrase in lower or phrase in text
        for phrase in (
            "in english",
            "into english",
            "to english",
            "translate to english",
            "translate into english",
            "reply in english",
            "respond in english",
            "answer in english",
            "use english",
            "english only",
            "翻譯成英語",
            "翻译成英语",
            "翻譯成英文",
            "翻译成英文",
            "翻成英語",
            "翻成英语",
            "翻成英文",
            "譯成英語",
            "译成英语",
            "譯成英文",
            "译成英文",
            "用英文",
            "用英語",
            "用英语",
        )
    ):
        return "en"
    if any(
        phrase in lower
        for phrase in (
            "traditional chinese",
            "繁體",
            "繁体",
            "zh_tw",
            "zh-tw",
            "taiwan",
            "翻譯成繁體",
            "翻译成繁体",
            "翻成繁體",
            "翻成繁体",
        )
    ):
        return "zh_tw"
    if any(
        phrase in lower or phrase in text
        for phrase in (
            "in chinese",
            "in mandarin",
            "chinese summary",
            "chinese translation",
            "simplified chinese",
            "简体中文",
            "简体",
            "翻譯成中文",
            "翻译成中文",
            "翻成中文",
            "譯成中文",
            "译成中文",
            "翻譯成简体",
            "翻译成简体",
            "中文",
            "汉语",
            "zh_cn",
            "zh-cn",
        )
    ):
        return "zh_cn"
    if any(phrase in lower for phrase in ("in french", "en français", "french summary")):
        return "en"  # no fr pack yet; rule still applied via custom line in profile
    if any(
        phrase in lower
        for phrase in (
            "in spanish", "into spanish", "to spanish", "translate to spanish",
            "translate into spanish", "reply in spanish", "respond in spanish",
            "answer in spanish", "use spanish", "spanish only", "en espa\u00f1ol",
            "en espanol", "en castellano", "traducir al espa\u00f1ol", "traducir al espanol",
            "traduce al espa\u00f1ol", "traduce al espanol", "responde en espa\u00f1ol",
            "responde en espanol", "contesta en espa\u00f1ol",
        )
    ):
        return "es"
    if any(
        phrase in lower
        for phrase in (
            "in german", "into german", "to german", "translate to german",
            "translate into german", "reply in german", "respond in german",
            "answer in german", "use german", "german only", "auf deutsch",
            "ins deutsche \u00fcbersetzen", "ins deutsche uebersetzen",
            "\u00fcbersetze ins deutsche", "uebersetze ins deutsche",
            "antworte auf deutsch",
        )
    ):
        return "de"
    if re.search(r"[\u4e00-\u9fff]", text):
        loc = get_locale()
        return loc if loc in ("zh_tw", "zh_cn") else "zh_cn"
    return None


def append_language_rule(system_text: str, locale: str | None = None) -> str:
    """Append settings-level language only (no profile/chat merge). Prefer apply_instruction_priority."""
    base = (system_text or "").rstrip()
    rule = language_system_rule(locale)
    if not rule:
        return base
    if base and "LANGUAGE:" in base and "Respond to the user entirely" in base:
        return base
    if not base:
        return rule
    return f"{base}\n\n{rule}"


def apply_locale_to_messages(
    messages: list[dict],
    *,
    locale: str | None = None,
) -> list[dict]:
    """Ensure the first system message includes the UI locale rule (extensions + shared LLM)."""
    if not messages:
        return []
    loc = normalize_locale(locale) if locale else get_locale()
    out = [dict(m) for m in messages]
    for i, m in enumerate(out):
        if (m.get("role") or "").lower() == "system":
            out[i] = {
                **m,
                "content": append_language_rule(str(m.get("content") or ""), locale=loc),
            }
            return out
    out.insert(0, {"role": "system", "content": language_system_rule(loc)})
    return out
